import sys
from collections import deque

def find_shortest_cycle(n, files, adj_list):
    def bfs(start):
        visited = {start: 0}
        queue = deque([start])
        parent = {start: None}

        while queue:
            node = queue.popleft()
            for neighbor in adj_list[node]:
                if neighbor not in visited:
                    visited[neighbor] = visited[node] + 1
                    parent[neighbor] = node
                    queue.append(neighbor)
                elif parent[node] != neighbor:
                    return reconstruct_cycle(node, neighbor, parent)
        return None

    def reconstruct_cycle(u, v, parent):
        path = []
        current = u
        while current != v:
            path.append(current)
            current = parent[current]
        path.append(v)
        path.append(u)
        return path[::-1]

    shortest_cycle = None
    for file in files:
        cycle = bfs(file)
        if cycle:
            if shortest_cycle is None or len(cycle) < len(shortest_cycle):
                shortest_cycle = cycle

    return shortest_cycle

def main():
    input = sys.stdin.read().splitlines()
    n = int(input[0])
    files = input[1].split()
    adj_list = {file: [] for file in files}

    index = 2
    for _ in range(n):
        file, k = input[index].split()
        k = int(k)
        index += 1
        for _ in range(k):
            imports = input[index].split('import ')[1].split(', ')
            adj_list[file].extend(imports)
            index += 1

    cycle = find_shortest_cycle(n, files, adj_list)
    if cycle:
        print(' '.join(cycle))
